var WALI_ALIH_ = [[/(^|[^a-z])gunarto([^a-z]|$)/i, 'Prof. Dr. H. Gunarto, S.H., M.H.'], [/bambang\s+tri\s+bawono/i, 'Prof. Dr. Bambang Tri Bawono, S.H., M.H.'], [/jawade\s+hafidz/i, 'Prof. Dr. H. Jawade Hafidz, S.H., M.H.']];
function waliDialihkan_(nama) {
