  if (/^belum ada/i.test(n)) return true;
  for (var i = 0; i < WALI_ALIH_.length; i++) if (WALI_ALIH_[i][0].test(n)) return true;
  return false;
}
function namaWaliAlih_(nama) { for (var i = 0; i < WALI_ALIH_.length; i++) if (WALI_ALIH_[i][0].test(String(nama))) return WALI_ALIH_[i][1]; return String(nama); }
function cekAturanNilai_(baris) {
  var h = { kurang: [], bc: [], ganda: [] }, lihat = {};
  (baris || []).forEach(function (b) {
    var kode = String(b.kode || ''), nama = String(b.nama || '').replace(/\s+/g, ' ').trim(), n = String(b.nilai || ''), tampil = MK_MIN_BC[kode] || nama || kode;
    if (kode) { if (lihat[kode]) { if (h.ganda.indexOf(lihat[kode]) < 0) h.ganda.push(lihat[kode]); } else lihat[kode] = tampil; }
    if (!n) return;
    if (n === 'CD' || n === 'D' || n === 'E') h.kurang.push({ nama: tampil, nilai: n });
    else if (n === 'C' && (MK_MIN_BC.hasOwnProperty(kode) || POLA_MIN_BC_.test(nama))) h.bc.push({ nama: tampil, nilai: n });
