  var p = [], sebut = function (l) { return l.slice(0, 6).map(function (x) { return x.nama + ' (' + x.nilai + ')'; }).join('; ') + (l.length > 6 ? '; dan ' + (l.length - 6) + ' lainnya' : ''); };
  if (a.kurang.length) p.push(a.kurang.length + ' mata kuliah bernilai di bawah C: ' + sebut(a.kurang));
  if (a.bc.length) p.push(a.bc.length + ' mata kuliah wajib minimal BC tetapi masih C: ' + sebut(a.bc));
  if (a.ganda.length) p.push(a.ganda.length + ' mata kuliah tercantum ganda: ' + a.ganda.slice(0, 6).join('; '));
  return 'Syarat nilai belum terpenuhi: ' + p.join('. Juga ') + '. Aturannya: semua mata kuliah minimal C, delapan mata kuliah dasar minimal BC, dan tidak ada mata kuliah ganda.';
