/* ------------------------------------------------------------------
 * Hitung IPK dari nilai yang diisi. nilai = { KODE: 'A' | 'AB' | ... }
 * ------------------------------------------------------------------ */
function hitungTranskrip_(nilai, kekhususan) {
  nilai = nilai || {};
  var sks = 0, mutu = 0, terisi = 0, total = 0, lulus = 0, nilaiD = 0;
  function tambah(mk) {
    total++;
    var n = nilai[mk[1]];
    if (n && BOBOT_NILAI.hasOwnProperty(n)) {
      sks += mk[2]; mutu += mk[2] * BOBOT_NILAI[n]; terisi++;
      if (n === 'D' || n === 'E') nilaiD++; else lulus += mk[2];
    }
  }
  KURIKULUM.forEach(function (s) { s.mk.forEach(function (mk) { if (mk[3] !== 'PK') tambah(mk); }); });
  (KURIKULUM_PK[kekhususan] || []).forEach(tambah);
  var m = nilai[KODE_MPH];
  return { sks: sks, lulus: lulus, nilaiD: nilaiD, mph: !!m && m !== 'D' && m !== 'E', mutu: mutu, terisi: terisi, total: total, ipk: sks ? Math.round(mutu / sks * 100) / 100 : 0 };
}

/* ==================================================================
 * CEK KEMIRIPAN JUDUL
 * ================================================================== */
var KATA_UMUM_ = (function () {
  var k = ('yang dan di ke dari dalam pada untuk dengan atas oleh terhadap sebagai tentang serta atau ' +
    'the of in and a an to on for by as at is are ' +
    'studi kasus nomor no tahun jo juncto pasal ayat uu ri ini itu para suatu sebuah secara bagi antara ' +
    'guna melalui agar adalah akan telah dapat').split(' ');
  var o = {}; k.forEach(function (x) { o[x] = 1; }); return o;
})();

function bersihkanJudul_(s) {
  return String(s == null ? '' : s).toLowerCase()
    .replace(/[‘’'`]/g, '')
    .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function tokenJudul_(s) {
  var kata = bersihkanJudul_(s).split(' '), o = {}, hasil = [];
  for (var i = 0; i < kata.length; i++) {
    var k = kata[i];
    if (!k || KATA_UMUM_[k]) continue;
    if (k.length > 5 && /nya$/.test(k)) k = k.slice(0, -3);
    if (k.length < 2 && !/\d/.test(k)) continue;
    if (!o[k]) { o[k] = 1; hasil.push(k); }
  }
  return hasil;
}

function jarakKetik_(a, b, batas) {
  if (Math.abs(a.length - b.length) > batas) return batas + 1;
  var prev = [], i, j;
  for (j = 0; j <= b.length; j++) prev[j] = j;
  for (i = 1; i <= a.length; i++) {
    var cur = [i], min = i;
    for (j = 1; j <= b.length; j++) {
      var v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1));
      cur[j] = v; if (v < min) min = v;
    }
    if (min > batas) return batas + 1;
    prev = cur;
  }
  return prev[b.length];
}

function kataMirip_(a, b) {
  if (a === b) return true;
  if (a.length < 5 || b.length < 5 || a.charAt(0) !== b.charAt(0)) return false;
  if (/\d/.test(a) || /\d/.test(b)) return false;
  var batas = Math.min(a.length, b.length) >= 9 ? 2 : 1;
  return jarakKetik_(a, b, batas) <= batas;
}

/** Susun bobot kata dari seluruh judul di database: kata langka berbobot besar. */
function susunBobot_(daftarToken) {
  var df = {}, n = daftarToken.length;
  for (var i = 0; i < n; i++) for (var j = 0; j < daftarToken[i].length; j++) {
    var t = daftarToken[i][j]; df[t] = (df[t] || 0) + 1;
  }
  return { df: df, n: n };
}
function bobotKata_(t, bobot) {
  var d = bobot.df[t] || 0;
  return Math.log((bobot.n + 2) / (d + 1)) + 0.15;
}

/** Skor 0–100 antara dua judul (dalam bentuk token). */
function skorToken_(A, B, bobot) {
  if (!A.length || !B.length) return 0;
  var setB = {}, pakaiB = {}, i, j;
  for (j = 0; j < B.length; j++) setB[B[j]] = 1;
  var wA = 0, wB = 0, sama = 0, sisaA = [];
  for (i = 0; i < A.length; i++) {
    var w = bobotKata_(A[i], bobot); wA += w;
    if (setB[A[i]]) { sama += w; pakaiB[A[i]] = 1; } else sisaA.push(A[i]);
  }
  for (j = 0; j < B.length; j++) wB += bobotKata_(B[j], bobot);
  for (i = 0; i < sisaA.length; i++) {
    for (j = 0; j < B.length; j++) {
      if (pakaiB[B[j]]) continue;
      if (kataMirip_(sisaA[i], B[j])) {
        sama += (bobotKata_(sisaA[i], bobot) + bobotKata_(B[j], bobot)) / 2;
        pakaiB[B[j]] = 1; break;
      }
    }
  }
  var dice = 2 * sama / (wA + wB);
  var muat = sama / Math.min(wA, wB);
  var skor = dice;
  // Satu judul nyaris seluruhnya termuat di judul lain (mis. hanya ditambah lokasi).
  if (Math.min(A.length, B.length) >= 4 && muat >= 0.9) skor = Math.max(skor, 0.55 + 0.35 * dice);
  return Math.max(0, Math.min(100, Math.round(skor * 100)));
}

/**
 * Bandingkan satu judul dengan korpus.
 * korpus = [{judul, token, sumber, tahun, nim}]
 */
function bandingkanDenganKorpus_(judul, korpus, bobot, nimSendiri) {
  var T = tokenJudul_(judul), bersih = bersihkanJudul_(judul), hasil = [];
  for (var i = 0; i < korpus.length; i++) {
    var k = korpus[i];
    if (nimSendiri && k.nim && String(k.nim) === String(nimSendiri)) continue;
    var s = (bersihkanJudul_(k.judul) === bersih) ? 100 : skorToken_(T, k.token, bobot);
    if (s >= 30) hasil.push({ judul: k.judul, sumber: k.sumber, tahun: k.tahun || '', skor: s });
  }
  hasil.sort(function (a, b) { return b.skor - a.skor; });
  return { skor: hasil.length ? hasil[0].skor : 0, mirip: hasil.slice(0, 4) };
}

function statusSkor_(skor, ambang) {
  if (skor >= ambang.merah) return 'MERAH';
  if (skor >= ambang.kuning) return 'KUNING';
  return 'HIJAU';
}

/* ==================================================================
 * NAMA DOSEN
 * ================================================================== */
var GELAR_ = (function () {
  var k = 'prof dr drs dra ir h hj hm hd sh mh mhum mkn cn spn sp se akt kn hum htn han hi spsi spd mm msi llm phd'.split(' ');
  var o = {}; k.forEach(function (x) { o[x] = 1; }); return o;
})();

function tokenNama_(nama) {
  var s = String(nama || '').toLowerCase().replace(/\([^)]*\)/g, ' ').replace(/[‘’'`]/g, '').replace(/[^a-z]+/g, ' ');
  var kata = s.split(' '), hasil = [];
  for (var i = 0; i < kata.length; i++) {
    if (kata[i].length < 3 && kata[i] !== 'ali') continue;
    if (GELAR_[kata[i]]) continue;
    hasil.push(kata[i]);
  }
  return hasil;
}
function namaMirip_(a, b) {
  if (a === b) return 1;
  if (a.length < 4 || b.length < 4) return 0;
  var pendek = Math.min(a.length, b.length);
  if (a.charAt(0) !== b.charAt(0)) return ((a.indexOf(b) >= 0 || b.indexOf(a) >= 0) && pendek >= 5) ? 0.8 : 0;
  if ((a.indexOf(b) === 0 || b.indexOf(a) === 0) && pendek >= 5) return 0.8;
  var batas = pendek >= 8 ? 2 : 1;
  return jarakKetik_(a, b, batas) <= batas ? 0.8 : 0;
}

/** Cari dosen baku yang cocok dengan ejaan bebas. Mengembalikan indeks atau -1. */
function cocokkanDosen_(ejaan, daftar) {
  var T = tokenNama_(ejaan);
  if (!T.length) return -1;
  var terbaik = -1, nilaiTerbaik = 0, seri = false;
  for (var i = 0; i < daftar.length; i++) {
    var D = daftar[i].token, cocok = 0, mutu = 0, pakai = {};
    for (var a = 0; a < T.length; a++) {
      var bTerbaik = -1, mTerbaik = 0;
      for (var b = 0; b < D.length; b++) {
        if (pakai[b]) continue;
        var m = namaMirip_(T[a], D[b]);
        if (m > mTerbaik) { mTerbaik = m; bTerbaik = b; }
      }
      if (bTerbaik >= 0) { cocok++; mutu += mTerbaik; pakai[bTerbaik] = 1; }
    }
    if (!cocok || cocok < Math.min(2, T.length, D.length)) continue;
    var nilai = mutu * 10 + cocok / Math.max(T.length, D.length);
    if (nilai > nilaiTerbaik + 1e-9) { nilaiTerbaik = nilai; terbaik = i; seri = false; }
    else if (Math.abs(nilai - nilaiTerbaik) < 1e-9) seri = true;
  }
  return seri ? -1 : terbaik;
}

function rapikanGelar_(nama) {
  var s = String(nama || '').replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim();
  s = s.replace(/\s*\.\s*,/g, ',').replace(/\.\s+(?=S\.H)/g, ', ').replace(/\s*,\s*/g, ', ');
  s = s.replace(/\b(S\.H|M\.H|M\.Hum|M\.Kn|Sp\.N|S\.E|C\.N|S\.Psi)(?=,|$)/g, '$1.');
  s = s.replace(/\bSH(?=,|$)/g, 'S.H.').replace(/\bMH(?=,|$)/g, 'M.H.').replace(/\bCN(?=,|$)/g, 'C.N.');
  var koma = s.indexOf(','), depan = koma < 0 ? s : s.slice(0, koma);
  depan = depan.replace(/(^|\s)([a-z])([a-z]{2,})/g, function (x, p, a, b) { return p + a.toUpperCase() + b; });
  s = koma < 0 ? depan : depan + s.slice(koma);
  return s.replace(/\.\./g, '.').replace(/[ ,]+$/, '');
}

/**
 * Susun daftar dosen baku dari dua tab pembimbing.
 * barisPidana / barisPerdata = nilai sel tab (array 2D).
 */
function susunDaftarDosen_(barisPidana, barisPerdata, tidakAktif) {
  var daftar = [];
  function ambil(baris, rumpun) {
    for (var i = 0; i < baris.length; i++) {
      var no = baris[i][0], nama = String(baris[i][1] || '').trim();
      if (!nama || !/^\d+$/.test(String(no).replace(/\.0$/, '').trim())) continue;
      var tag = (nama.match(/\(([^)]+)\)/) || [])[1] || '';
      var d = { nama: rapikanGelar_(nama), rumpun: rumpun, bidang: tag.toUpperCase().trim(), token: tokenNama_(nama), aktif: true };
      if (cocokkanDosen_(nama, daftar) >= 0) continue;
      daftar.push(d);
    }
  }
  ambil(barisPidana || [], 'Pidana');
  ambil(barisPerdata || [], 'Perdata');
  (tidakAktif || []).forEach(function (n) {
    var i = cocokkanDosen_(n, daftar); if (i >= 0) daftar[i].aktif = false;
  });
  return daftar;
}

/** Calon pembimbing untuk satu kekhususan, urut dari beban paling ringan. */
function calonPembimbing_(kekhususan, dosenWali, daftar, beban) {
  var bidang = { 'Hukum Tata Negara': 'HTN', 'Hukum Administrasi Negara': 'HAN', 'Hukum Internasional': 'HI' }[kekhususan];
  var rumpun = (kekhususan === 'Hukum Perdata' || kekhususan === 'Hukum Islam') ? 'Perdata' : 'Pidana';
  var iWali = dosenWali ? cocokkanDosen_(dosenWali, daftar) : -1;
  function saring(f) {
    var h = [];
    for (var i = 0; i < daftar.length; i++) {
      if (!daftar[i].aktif || i === iWali) continue;
      if (f(daftar[i])) h.push({ nama: daftar[i].nama, rumpun: daftar[i].rumpun, bidang: daftar[i].bidang, beban: beban[i] || 0, urut: i });
    }
    return h;
  }
  var calon = bidang ? saring(function (d) { return d.bidang === bidang; }) : [];
  if (!calon.length) calon = saring(function (d) { return d.rumpun === rumpun; });
  // Dosen yang sudah membimbing semester ini didahulukan; yang belum pernah
  // (umumnya pejabat/guru besar yang tidak membimbing S1) ditaruh di akhir.
  var adaYangAktif = calon.some(function (c) { return c.beban > 0; });
  calon.forEach(function (c) { c.belum = adaYangAktif && c.beban === 0; });
  calon.sort(function (a, b) { return (a.belum ? 1 : 0) - (b.belum ? 1 : 0) || a.beban - b.beban || a.urut - b.urut; });
  return calon;
}

