    if (b.kode === KODE_MPH || /\bMPH\b|METOD[EO]\w*\s+PENELITIAN/i.test(b.nama)) h.mph = { ada: true, nilai: b.nilai };
  });
  h.ipk = h.sks ? Math.round(h.mutu / h.sks * 100) / 100 : 0;
  h.aturan = cekAturanNilai_(h.baris);

  if (!h.nim) h.catatan.push('NIM pada DKN tidak terbaca.');
  if (!kode.length) h.catatan.push('Baris mata kuliah tidak terbaca.');
  else if (terbaca.length < kode.length) h.catatan.push((kode.length - terbaca.length) + ' dari ' + kode.length + ' baris mata kuliah nilainya tidak terbaca.');
  if (h.jumlahSks === null) h.catatan.push('JUMLAH SKS di akhir DKN tidak terbaca. Pastikan halaman terakhir ikut diunggah.');
  else if (kode.length && h.sks !== h.jumlahSks) h.catatan.push('Jumlah SKS baris yang terbaca (' + h.sks + ') tidak sama dengan JUMLAH SKS pada DKN (' + h.jumlahSks + ').');
  if (h.ip === null) h.catatan.push('INDEX PRESTASI di akhir DKN tidak terbaca.');
  else if (h.sks && Math.abs(h.mutu / h.sks - h.ip) > 0.0101) h.catatan.push('IPK hasil hitung (' + h.ipk.toFixed(2) + ') tidak sama dengan INDEX PRESTASI pada DKN (' + h.ip.toFixed(2) + ').');

  var cocok = !!h.nim && kode.length >= 10 && terbaca.length === kode.length && yakin.length === kode.length &&
    h.jumlahSks !== null && h.sks === h.jumlahSks && h.ip !== null && Math.abs(h.mutu / h.sks - h.ip) <= 0.0101;
  h.status = cocok ? 'cocok' : 'periksa';
  if (cocok) { h.ipk = h.ip; h.catatan = []; return h; }
  /* Foto/scan: Google membaca tabel per kolom sehingga nilai tidak bisa dipasangkan dengan mata kuliahnya.
     Bila kepala dan kaki DKN terbaca, JUMLAH SKS dan INDEX PRESTASI tetap diambil dari DKN (status "kaki"). */
  var semuaKenal = kode.length > 0, sksDaftar = 0;
  kode.forEach(function (x) { if (sksMk[x.kode]) sksDaftar += sksMk[x.kode]; else semuaKenal = false; });
  h.cekSks = !semuaKenal ? 'takdiketahui' : (sksDaftar === h.jumlahSks ? 'sama' : 'beda');
  h.sksDaftar = sksDaftar;
  h.dugaD = /(?:^|\n)\s*(?:\d\s+)?[DE]\s*(?:\d{1,2}\s*)?(?=\r?\n|$)/.test(t.slice(kode.length ? kode[0].awal : 0));
  if (!h.mph.ada) kode.forEach(function (x) { if (x.kode === KODE_MPH) h.mph = { ada: true, nilai: '' }; });
  if (h.nim && kode.length >= 10 && terbaca.length * 2 < kode.length && h.jumlahSks !== null && h.ip !== null && /KUMPULAN\s+NILA/i.test(t)) {
    h.status = 'kaki';
    h.catatan = ['Nilai per mata kuliah tidak bisa dipasangkan dari foto ini, jadi hanya JUMLAH SKS (' + h.jumlahSks + ') dan INDEX PRESTASI (' + h.ip.toFixed(2).replace('.', ',') + ') yang diambil dari DKN.',
      h.cekSks === 'sama' ? 'Jumlah SKS dari ' + kode.length + ' kode mata kuliah yang terbaca sama dengan JUMLAH SKS pada DKN.'
        : (h.cekSks === 'beda' ? 'Jumlah SKS dari ' + kode.length + ' kode mata kuliah yang terbaca (' + sksDaftar + ') berbeda dari JUMLAH SKS pada DKN (' + h.jumlahSks + '); mungkin ada baris yang tidak terbaca.'
          : 'Sebagian kode mata kuliah bukan dari kurikulum 2023, jadi jumlah SKS tidak bisa dicocokkan dengan daftar.')];
    if (h.dugaD) h.catatan.push('Terbaca huruf D atau E di kolom nilai. Periksa berkasnya.');
  }
  return h;
}

