/* ------------------------------ kas (cache) ------------------------------
   Log in dan muat ulang harus cepat: jawaban layanan baca disimpan sebentar di CacheService (dibagi
   per 90 KB bila besar), pengaturan disimpan 2 menit, dan pemeriksaan struktur buku (pastikan_) cukup
   sekali tiap 6 jam. Semua layanan yang menulis data membatalkan kas (lihat doPost). */
var SERVER_VERSI_ = 34, KAS_VERSI_ = 'k' + SERVER_VERSI_, MEMO_ = {};
function kas_() { try { return CacheService.getScriptCache(); } catch (e) { return null; } }
function kasGen_() {
  var c = kas_(); if (!c) return '0';
  var g = c.get(KAS_VERSI_ + '.gen');
  if (!g) { g = String(Date.now()); try { c.put(KAS_VERSI_ + '.gen', g, 21600); } catch (e) {} }
  return g;
}
/** Semua kas data dianggap kedaluwarsa (dipanggil tiap ada perubahan data). */
function kasBatal_() { MEMO_ = { atur: MEMO_.atur }; var c = kas_(); if (c) { try { c.put(KAS_VERSI_ + '.gen', String(Date.now()), 21600); } catch (e) {} } }
function kasKunci_(kunci) { return KAS_VERSI_ + '.' + kasGen_() + '.' + kunci; }
function kasAmbil_(kunci, tetap) {
  var c = kas_(); if (!c) return null;
  var k = tetap ? KAS_VERSI_ + '.' + kunci : kasKunci_(kunci), kepala = c.get(k);
  if (kepala == null) return null;
  if (kepala.charAt(0) !== '\u0001') return kepala;
  var n = parseInt(kepala.slice(1), 10), daftar = [];
  for (var i = 0; i < n; i++) daftar.push(k + '#' + i);
  var peta = c.getAll(daftar), s = '';
  for (i = 0; i < n; i++) { if (peta[k + '#' + i] == null) return null; s += peta[k + '#' + i]; }
  return s;
}
function kasSimpan_(kunci, teks, detik, tetap) {
  var c = kas_(); if (!c || teks == null) return;
  var k = tetap ? KAS_VERSI_ + '.' + kunci : kasKunci_(kunci), B = 90000;
  try {
    if (teks.length <= B) { c.put(k, teks, detik); return; }
    var n = Math.ceil(teks.length / B), peta = {};
    if (n > 20) return;                                            // terlalu besar untuk kas
    for (var i = 0; i < n; i++) peta[k + '#' + i] = teks.substr(i * B, B);
    peta[k] = '\u0001' + n;
    c.putAll(peta, detik);
  } catch (e) { /* kas penuh / gagal: lewati */ }
}
function kasHapus_(kunci, tetap) { var c = kas_(); if (c) { try { c.remove(tetap ? KAS_VERSI_ + '.' + kunci : kasKunci_(kunci)); } catch (e) {} } }
/** Jawaban (teks JSON) layanan baca: dari kas bila ada; bila tidak, dihitung lalu disimpan. */
function kasJawab_(kunci, detik, hitung, segar) {
  if (!segar) { var ada = kasAmbil_(kunci); if (ada != null) return ada; }
  MEMO_.bacaSaja = true; MEMO_.masuk = null; MEMO_.kontak = null; MEMO_.tab = {};
  var teks;
  try { teks = hitung(); } finally { MEMO_.bacaSaja = false; }
  kasSimpan_(kunci, teks, detik);
  return teks;
}
function sidik_(s) {
  var b = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, String(s), Utilities.Charset.UTF_8), h = '';
  for (var i = 0; i < b.length; i++) { var v = (b[i] + 256) % 256; h += (v < 16 ? '0' : '') + v.toString(16); }
  return h;
}
/** Catatan galat server terakhir (untuk pemantauan), tanpa isi permintaan. */
function catatGalat_(fn, pesan) {
  try {
    var c = kas_(); if (!c) return;
    var d = []; try { d = JSON.parse(c.get(KAS_VERSI_ + '.galat') || '[]'); } catch (e) { d = []; }
    d.push({ waktu: waktuKini_(), fn: fn, pesan: String(pesan).slice(0, 200) });
    c.put(KAS_VERSI_ + '.galat', JSON.stringify(d.slice(-20)), 21600);
  } catch (e) {}
}
/** Kesehatan server untuk pemantauan otomatis: versi, kas, waktu, galat terakhir. Tidak memuat data sensitif. */
function apiSehat(perbaiki) {
  var mulai = Date.now(), ok = true, pesan = '';
  try { if (perbaiki === 'perbaiki') { kasHapus_('pastikan', true); kasBatal_(); } pastikan_(); bacaAtur_(); } catch (e) { ok = false; pesan = String(e.message || e); }
