    if (b[0] === 'Kode Kaprodi') nilai = acak_(7, '23456789');
    if (b[0] === 'Kode Admin Sidang') nilai = acak_(8, '23456789');
    if (b[0] === 'Kode Wakil Dekan I') nilai = acak_(9, '23456789');
    tambah.push([b[0], nilai, b[2]]);
  });
  if (tambah.length) {
