/** Baca tab daftar judul (letak baris judul kolom dicari otomatis). */
function bacaTabJudul_(namaTab) {
  if (MEMO_.bacaSaja && MEMO_.tab && MEMO_.tab[namaTab]) return MEMO_.tab[namaTab];
  var hasil = bacaTabJudulMentah_(namaTab);
  if (MEMO_.bacaSaja && MEMO_.tab) MEMO_.tab[namaTab] = hasil;
  return hasil;
}
function bacaTabJudulMentah_(namaTab) {
  var sh = buku_().getSheetByName(namaTab);
  if (!sh) return { ada: false, baris: [] };
  var isi = sh.getDataRange().getValues(), hk = -1, kol = {};
  for (var r = 0; r < Math.min(isi.length, 8) && hk < 0; r++) {
    var k = {};
    for (var c = 0; c < isi[r].length; c++) {
      var s = teks_(isi[r][c]).toLowerCase();
      if (!s) continue;
      if (/^no\.?$/.test(s) && k.no == null) k.no = c;
      else if (/nim/.test(s) && k.nim == null) k.nim = c;
      else if (/judul/.test(s) && k.judul == null) k.judul = c;
      else if (/nama/.test(s) && k.nama == null) k.nama = c;
      else if (/dosen|pembimbing/.test(s) && k.dosen == null) k.dosen = c;
      else if (/tgl|tanggal/.test(s) && k.tanggal == null) k.tanggal = c;
      else if (/kekhususan/.test(s) && k.kekhususan == null) k.kekhususan = c;
    }
    if (k.nim != null && k.judul != null) { hk = r; kol = k; }
  }
  if (hk < 0) return { ada: true, baris: [], kepala: -1, kol: {} };
  var baris = [], akhir = hk, noAkhir = 0, jumlahIsi = 0;
  for (var i = hk + 1; i < isi.length; i++) {
    var judul = teks_(isi[i][kol.judul]), nama = kol.nama != null ? teks_(isi[i][kol.nama]) : '';
    if (!judul && !nama) continue;
    akhir = i; jumlahIsi++;
    var no = kol.no != null ? parseInt(isi[i][kol.no], 10) : NaN;
    if (!isNaN(no) && no > noAkhir) noAkhir = no;
    if (!judul) continue;
    baris.push({
      nama: nama, nim: teks_(isi[i][kol.nim]).replace(/\.0$/, ''), judul: judul,
      dosen: kol.dosen != null ? teks_(isi[i][kol.dosen]) : '',
      tahun: kol.tanggal != null ? tahunDari_(isi[i][kol.tanggal]) : '',
      kekhususan: kol.kekhususan != null ? teks_(isi[i][kol.kekhususan]) : ''
    });
  }
  return { ada: true, baris: baris, kepala: hk, kol: kol, barisAkhir: akhir, noAkhir: Math.max(noAkhir, jumlahIsi), lembar: sh };
}

function bacaMasuk_() {
