/** Seluruh judul pembanding: arsip, semester berjalan, dan pengajuan yang sedang berjalan. */
function susunKorpus_(masuk) {
  var korpus = [];
  function tambah(tab, label) {
    bacaTabJudul_(tab).baris.forEach(function (b) {
      korpus.push({ judul: b.judul, token: tokenJudul_(b.judul), sumber: label + (b.tahun ? ' ' + b.tahun : ''), nim: b.nim });
    });
  }
  var kasTab = kasAmbil_('korpusTab');
  if (kasTab) korpus = JSON.parse(kasTab);
  else {
    tambah(KONFIG.TAB_ARSIP, 'Arsip prodi');
    tambah(KONFIG.TAB_REGULER, 'Sudah disetujui');
    tambah(KONFIG.TAB_EKS, 'Sudah disetujui');
    kasSimpan_('korpusTab', JSON.stringify(korpus), 600);
  }
  (masuk || bacaMasuk_()).baris.forEach(function (o) {
    var r = rekaman_(o);
    if (r.status === 'Menunggu' || r.status === 'Menunggu Wali' || r.status === 'Menunggu WD1') {
      r.judul.forEach(function (j) { if (j) korpus.push({ judul: j, token: tokenJudul_(j), sumber: 'Sedang diajukan mahasiswa lain', nim: r.nim }); });
    } else if (r.status === 'ACC' && !r.tersinkron && r.judulDisetujui) {
      korpus.push({ judul: r.judulDisetujui, token: tokenJudul_(r.judulDisetujui), sumber: 'Sudah disetujui', nim: r.nim });
    }
  });
  return { korpus: korpus, bobot: susunBobot_(korpus.map(function (k) { return k.token; })) };
}

