  var T = tokenJudul_(judul), q = encodeURIComponent(judul);
  var berat = T.slice().sort(function (a, b) { return bobotKata_(b, bobot) - bobotKata_(a, bobot); }).slice(0, 4);
  var mail = atur.email ? '&mailto=' + encodeURIComponent(atur.email) : '';
  var daftar = [
    { nama: 'OpenAlex', url: 'https://api.openalex.org/works?search=' + q + '&per-page=15&select=id,title,publication_year' + mail,
      urai: function (t) { return (JSON.parse(t).results || []).map(function (w) { return { judul: w.title, url: w.id, tahun: w.publication_year }; }); } },
    { nama: 'Crossref', url: 'https://api.crossref.org/works?query.bibliographic=' + q + '&rows=15&select=title,URL' + mail,
      urai: function (t) { return ((JSON.parse(t).message || {}).items || []).map(function (w) { return { judul: (w.title || [])[0], url: w.URL }; }); } },
    { nama: 'Repository UNISSULA', url: 'https://repository.unissula.ac.id/cgi/search/simple?q=' + encodeURIComponent(berat.join(' ')) + '&_action_search=Search&_order=bytitle&basic_srchtype=ALL&_satisfyall=ALL',
      urai: function (t) {
        var h = [], re = /<a href="(https?:\/\/repository\.unissula\.ac\.id\/[^"]*?\d+\/?)"[^>]*>\s*<em>([\s\S]*?)<\/em>/g, m;
        while ((m = re.exec(t)) && h.length < 30) h.push({ judul: m[2].replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, '\''), url: m[1] });
        if (!h.length && !/ep_|eprints/i.test(t)) throw new Error('halaman tidak dikenali');
