      urai: function (t) { return (JSON.parse(t).items || []).map(function (w) { return { judul: w.title, kutipan: w.snippet, url: w.link }; }); } });
  }
  var jawab = [];
  try {
    jawab = UrlFetchApp.fetchAll(daftar.map(function (d) {
      return { url: d.url, muteHttpExceptions: true, followRedirects: true, headers: { 'Accept': 'application/json,text/html' } };
    }));
  } catch (e) {
    // fetchAll gagal seluruhnya bila satu alamat tak terjangkau: coba satu per satu.
    jawab = daftar.map(function (d) {
      try { return UrlFetchApp.fetch(d.url, { muteHttpExceptions: true }); } catch (x) { return null; }
    });
  }
  var bersih = bersihkanJudul_(judul), semua = [];
  daftar.forEach(function (d, i) {
    var info = { nama: d.nama, ok: false, jumlah: 0 };
    try {
      var r = jawab[i];
