            var H = tokenJudul_(w.judul + ' ' + (w.kutipan || '')), ada = {}, wT = 0, wS = 0;
            H.forEach(function (x) { ada[x] = 1; });
            T.forEach(function (x) { var b = bobotKata_(x, bobot); wT += b; if (ada[x]) wS += b; });
            s = wT ? Math.round(100 * wS / wT * 0.9) : 0;
          } else {
            s = bersihkanJudul_(w.judul) === bersih ? 100 : skorToken_(T, tokenJudul_(w.judul), bobot);
          }
          if (s >= 30) semua.push({ judul: teks_(w.judul).slice(0, 300), sumber: d.nama, url: w.url || '', tahun: w.tahun || '', skor: s });
        });
