    } catch (e) { info.ok = false; info.galat = String(e.message || e).slice(0, 80); }
    hasil.sumber.push(info);
  });
  semua.sort(function (a, b) { return b.skor - a.skor; });
  hasil.mirip = semua.slice(0, 3);
  hasil.skor = semua.length ? semua[0].skor : 0;
  if (cache && hasil.terjangkau === daftar.length) { try { cache.put(kunci, JSON.stringify(hasil), 21600); } catch (e) { /* abaikan */ } }
  return hasil;
}

