/** Lembar penyimpanan scan KRS: spreadsheet arsip tersendiri, atau tab di spreadsheet utama bila arsip tidak bisa dibuat. */
/** Buku arsip KRS: buku terpisah agar buku utama tetap ringan; berganti buku baru tiap 120 berkas. */
function lembarKrs_(idBuku, untukTulis, namaTab) {
  var ss = null, NAMA = namaTab || 'BERKAS KRS';
  if (idBuku === 'utama') ss = buku_();
