  if (ss && untukTulis && idBuku !== 'utama') { var ada = ss.getSheetByName(NAMA); if (ada && ada.getLastRow() > 120) ss = null; }
  if (!ss) {
    if (!untukTulis) return null;
    try {
      ss = SpreadsheetApp.create('ARSIP KRS - Pengajuan Judul Skripsi FH UNISSULA (' + Utilities.formatDate(new Date(), 'Asia/Jakarta', 'yyyy-MM-dd') + ')');
      idBuku = ss.getId(); tulisAtur_('ID Arsip KRS', idBuku);
    } catch (e) { ss = buku_(); idBuku = 'utama'; }
  }
  var sh = ss.getSheetByName(NAMA);
  if (!sh) {
    if (!untukTulis) return null;
    sh = ss.insertSheet(NAMA);
    sh.getRange(1, 1, 1, 8).setValues([['ID', 'NIM', 'Nama', 'Jenis', 'Nama Berkas', 'Ukuran (KB)', 'Waktu', 'Isi (jangan diubah)']]).setFontWeight('bold');
    if (idBuku === 'utama') { try { sh.hideSheet(); } catch (e) {} }
  }
