  if (mime !== 'image/jpeg' && mime !== 'application/pdf') galat_('Berkas KRS harus berupa gambar (JPG/PNG) atau PDF.');
  if (b64.length > 950000 || !/^[A-Za-z0-9+\/=]+$/.test(b64)) galat_('Berkas KRS terlalu besar atau rusak. Unggah ulang dengan ukuran lebih kecil.');
  return { mime: mime, nama: teks_(krs.nama).replace(/[^\w. ()-]+/g, '_').slice(0, 80) || 'KRS', b64: b64, kb: Math.round(b64.length * 0.75 / 1024) };
}
