  if (typeof Drive === 'undefined' || !Drive.Files) galat_('Pembaca DKN belum diaktifkan di server (layanan Drive API). Hubungi pengelola prodi.');
  var blob = Utilities.newBlob(Utilities.base64Decode(b.b64), b.mime, b.nama), id = '';
  var meta = { mimeType: 'application/vnd.google-apps.document' };
  if (Drive.Files.create) { meta.name = 'SKRIPSPACE baca DKN (sementara)'; id = Drive.Files.create(meta, blob, { ocrLanguage: 'id', fields: 'id' }).id; }
  else { meta.title = 'SKRIPSPACE baca DKN (sementara)'; id = Drive.Files.insert(meta, blob, { ocr: true, ocrLanguage: 'id' }).id; }
  try {
    var jawab = UrlFetchApp.fetch('https://www.googleapis.com/drive/v3/files/' + id + '/export?mimeType=text%2Fplain',
      { headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true });
    if (jawab.getResponseCode() !== 200) galat_('Berkas tidak bisa dibaca server (' + jawab.getResponseCode() + ').');
    return jawab.getContentText('UTF-8');
  } finally { try { if (Drive.Files.remove) Drive.Files.remove(id); else Drive.Files.trash(id); } catch (e) {} }
}
