    if (!dk.mph.ada && !mphKrs) galat_('Mata kuliah Metode Penelitian Hukum tidak ada di DKN-mu. Syaratnya sudah lulus, atau sedang ditempuh semester ini dan tercantum pada KRS yang kamu unggah (centang pernyataannya).');
