    if (!d.tanpaD) galat_('Syarat nilai: semua mata kuliah minimal C, delapan mata kuliah dasar minimal BC, dan tidak ada mata kuliah ganda. Centang pernyataannya bila memang demikian.');
    if (!d.lulusMph && !mphKrs) galat_('Syarat mengajukan skripsi: sudah lulus Metode Penelitian Hukum, atau sedang menempuhnya semester ini dan tercantum pada KRS yang diunggah.');
    if (!d.lulusMph) p.mphKrs = true;
