    KURIKULUM_PK[p.kekhususan].forEach(function (mk) { sah[mk[1]] = 1; });
    for (var k in (d.nilai || {})) if (sah[k] && BOBOT_NILAI.hasOwnProperty(d.nilai[k])) p.nilai[k] = d.nilai[k];
    var t = hitungTranskrip_(p.nilai, p.kekhususan);
    var at = aturanDariNilai_(p.nilai, p.kekhususan);
    if (!aturanBersih_(at)) galat_(pesanAturan_(at));
    if (t.lulus < sksMin) galat_('Baru ' + t.lulus + ' SKS yang diselesaikan. Syarat mengajukan skripsi minimal ' + sksMin + ' SKS.');
    if (!t.mph && !mphKrs) galat_('Mata kuliah Metode Penelitian Hukum belum lulus. Bila sedang kamu tempuh semester ini, centang pernyataan bahwa mata kuliah itu tercantum pada KRS yang kamu unggah.');
