/* =====================================================================
 * IZIN RISET
 * Mahasiswa mengisi data diri, penelitian, dan instansi tujuan (satu permohonan per instansi);
 * setelah disetujui Kaprodi, dua surat terbit: permohonan (mahasiswa) dan pengantar (Kaprodi).
 * ===================================================================== */
var KOLOM_RISET_ = ['ID', 'Waktu', 'Kode', 'Status', 'NIM', 'Nama', 'Kelas', 'No WA', 'Dosen Pembimbing', 'Judul', 'Instansi', 'Pimpinan', 'Nomor Surat', 'Tgl Keputusan', 'Catatan'];
function bacaRiset_() {
  var ss = buku_(), sh = ss.getSheetByName(KONFIG.TAB_RISET);
  if (!sh) {
