    sh.getRange(1, 1, 1, KOLOM_RISET_.length).setValues([KOLOM_RISET_]).setFontWeight('bold');
    sh.setFrozenRows(1);
  }
  var isi = sh.getDataRange().getValues(), kepala = isi[0].map(teks_), kol = {}, baris = [];
  KOLOM_RISET_.forEach(function (k) {
    if (kepala.indexOf(k) < 0) { kepala.push(k); sh.getRange(1, kepala.length).setValue(k).setFontWeight('bold'); }
  });
  kepala.forEach(function (k, i) { if (k) kol[k] = i; });
  for (var r = 1; r < isi.length; r++) {
    if (!teks_(isi[r][kol['ID']])) continue;
    var o = { _baris: r + 1 };
    for (var k in kol) o[k] = isi[r][kol[k]];
    baris.push(o);
  }
  return { lembar: sh, kol: kol, kepala: kepala, baris: baris };
}
function riset_(o) {
