    kelas: teks_(o['Kelas']), wa: teks_(o['No WA']), dosenPembimbing: teks_(o['Dosen Pembimbing']), judul: teks_(o['Judul']), instansi: teks_(o['Instansi']), pimpinan: teks_(o['Pimpinan']),
