    bacaTabJudul_(t).baris.forEach(function (b) { if (b.nim) peta[b.nim] = { nama: b.nama, judul: b.judul, dosen: b.dosen }; });
  });
  (masuk || bacaMasuk_()).baris.map(rekaman_).forEach(function (r) {
