function cekPin_(pin, bolehSidang) {
  var atur = bacaAtur_(), cache = null, gagal = 0;
  try { cache = CacheService.getScriptCache(); gagal = parseInt(cache.get('pin-gagal') || '0', 10); } catch (e) { cache = null; }
  if (gagal >= 8) galat_('Terlalu banyak percobaan. Coba lagi 10 menit lagi.');
  var p = teks_(pin), peran = '';
  /* Satu kode pengelola (baris "PIN Admin") dipakai Sekprodi dan Kaprodi, dengan hak penuh.
     "Kode Kaprodi" lama, bila masih terisi, tetap diterima dengan hak yang sama. */
  if (p && atur.pin && p === atur.pin) peran = 'prodi';
  else if (p && atur.kodeKaprodi && p === atur.kodeKaprodi) peran = 'prodi';
  else if (p && atur.kodeSidang && atur.kodeSidang.length >= 6 && p === atur.kodeSidang) peran = 'sidang';
  else if (p && atur.kodeWd1 && atur.kodeWd1.length >= 6 && p === atur.kodeWd1) peran = 'wd1';
  if (!peran) {
    if (cache) { try { cache.put('pin-gagal', String(gagal + 1), 600); } catch (e) { /* abaikan */ } }
    galat_('Kode akses salah.');
  }
  /* admin pengajuan sidang hanya boleh memanggil layanan sidang */
  if (peran === 'sidang' && bolehSidang !== true && bolehSidang !== 'semua') galat_('Kode ini hanya untuk admin pengajuan sidang. Bagian ini memerlukan kode pengelola prodi.');
  /* Wakil Dekan I hanya boleh memanggil layanan persetujuan WD I */
  if (peran === 'wd1' && bolehSidang !== 'wd1' && bolehSidang !== 'semua') galat_('Kode ini hanya untuk Wakil Dekan I. Bagian ini memerlukan kode pengelola prodi.');
  atur.peran = peran;
  return atur;
}

