/* =====================================================================
 * Bagian 3: RUANG KERJA SKRIPSPACE
 * Tiga jenis masuk: mahasiswa (NIM + kode pengajuan), dosen pembimbing (kode
 * akses pribadi), dan pengelola prodi (PIN Admin / Kode Kaprodi). Ketiganya
 * membuka "ruang" yang sama untuk satu mahasiswa: rekam tahapan, catatan
 * bimbingan, dan pesan; hak ubahnya berbeda.
 * ===================================================================== */
var TAHAPAN_ = ['Pengajuan dan persetujuan judul skripsi', 'Penetapan dosen pembimbing', 'Penyusunan proposal skripsi',
  'Persetujuan proposal skripsi oleh dosen pembimbing', 'Pelaksanaan penelitian dan pengumpulan data', 'Penyusunan Bab I sampai dengan Bab IV',
  'Uji plagiarisme melalui Turnitin (maksimal 24,99%)', 'Persetujuan naskah skripsi untuk diujikan', 'Pelaksanaan ujian skripsi',
  'Perbaikan pasca-ujian dan penyerahan naskah akhir'];
var KOLOM_BIMBINGAN_ = ['ID', 'Waktu', 'ID Pengajuan', 'NIM', 'Tanggal', 'Bentuk', 'Materi', 'Catatan Dosen', 'Durasi', 'Paraf Mahasiswa', 'Paraf Dosen', 'Dibuat Oleh'];
var KOLOM_PESAN_ = ['ID', 'Waktu', 'ID Pengajuan', 'NIM', 'Dari', 'Nama', 'Isi'];

/** Baca satu tab data berjudul kolom; tab dan kolom yang belum ada dibuat. */
function tabData_(nama, kolom) {
  var ss = buku_(), sh = ss.getSheetByName(nama);
  if (!sh) {
    sh = ss.insertSheet(nama);
    sh.getRange(1, 1, 1, kolom.length).setValues([kolom]).setFontWeight('bold');
    sh.setFrozenRows(1);
  }
  var isi = sh.getDataRange().getValues(), kepala = isi[0].map(teks_), kol = {}, baris = [];
  kolom.forEach(function (k) {
    if (kepala.indexOf(k) >= 0) return;
    kepala.push(k);
    try { if (sh.getMaxColumns() < kepala.length) sh.insertColumnsAfter(sh.getMaxColumns(), kepala.length - sh.getMaxColumns()); } catch (e) { /* abaikan */ }
    sh.getRange(1, kepala.length).setValue(k).setFontWeight('bold');
  });
  kepala.forEach(function (k, i) { if (k) kol[k] = i; });
  for (var r = 1; r < isi.length; r++) {
    if (!teks_(isi[r][kol['ID']])) continue;
    var o = { _baris: r + 1 };
    for (var k in kol) o[k] = isi[r][kol[k]];
