}
function tambahBaris_(t, o) {
  t.lembar.getRange(barisBaru_(t.lembar), 1, 1, t.kepala.length).setNumberFormat('@')
    .setValues([t.kepala.map(function (k) { return o.hasOwnProperty(k) ? String(o[k]) : ''; })]);
}
function ubahSel_(t, baris, o) {
  for (var k in o) if (t.kol[k] != null) t.lembar.getRange(baris, t.kol[k] + 1).setNumberFormat('@').setValue(String(o[k]));
}
function idBaru_(awalan) { return awalan + Utilities.formatDate(new Date(), 'Asia/Jakarta', 'yyMMddHHmmss') + acak_(3, '0123456789'); }
function selisihHari_(isoAwal, isoAkhir) {
  var a = String(isoAwal || '').slice(0, 10).split('-'), b = String(isoAkhir || '').slice(0, 10).split('-');
  if (a.length < 3 || b.length < 3) return 0;
  return Math.round((Date.UTC(+b[0], b[1] - 1, +b[2]) - Date.UTC(+a[0], a[1] - 1, +a[2])) / 86400000);
}

/* ------------------------- kode akses dosen ------------------------- */
/** Pastikan tiap dosen pembimbing punya baris dan kode akses di tab KONTAK DOSEN. */
function siapkanKodeDosen_(atur) {
  var sh = buku_().getSheetByName(KONFIG.TAB_KONTAK);
  if (!sh) return;
  if (teks_(sh.getRange(1, 3).getValue()) !== 'Kode Akses') sh.getRange(1, 3).setValue('Kode Akses').setFontWeight('bold');
  var kontak = bacaKontak_(), pakai = {};
  daftarDosen_(atur).forEach(function (d) {
    if (cocokkanDosen_(d.nama, kontak) < 0) { sh.getRange(barisBaru_(sh), 1, 1, 2).setNumberFormat('@').setValues([[d.nama, '']]); MEMO_.kontak = null; }
  });
  kontak = bacaKontak_();
  kontak.forEach(function (k) { if (k.kode) pakai[k.kode] = 1; });
  kontak.forEach(function (k) {
    if (k.kode) return;
    var kode; do { kode = acak_(8, 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'); } while (pakai[kode]);
    pakai[kode] = 1; k.kode = kode;
    sh.getRange(k._baris, 3).setNumberFormat('@').setValue(kode);
  });
}
function cekDosen_(kode) {
  var k = teks_(kode).toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (k.length < 6) galat_('Isi kode akses dosen.');
  var kontak = bacaKontak_();
  for (var i = 0; i < kontak.length; i++) if (kontak[i].kode && kontak[i].kode === k) return { i: i, nama: rapikanGelar_(kontak[i].nama), kontak: kontak };
  galat_('Kode akses dosen salah. Minta kode Anda ke pengelola Prodi.');
}

/* ----------------------------- isi ruang ----------------------------- */
function tahapRek_(r) {
  var t = {};
  try { t = JSON.parse(r.tahapMentah || '{}'); } catch (e) { t = {}; }
  var tgl = t.t || {}, kini = 0;
  if (r.status === 'ACC') { if (!tgl[1]) tgl[1] = r.tanggalKeputusan; if (!tgl[2]) tgl[2] = r.tanggalKeputusan; }
  for (var i = 1; i <= TAHAPAN_.length; i++) if (!tgl[i]) { kini = i; break; }
  return { daftar: TAHAPAN_.map(function (n, j) { return { no: j + 1, nama: n, tanggal: tgl[j + 1] || '' }; }), kini: kini, turnitin: teks_(t.turnitin), mentah: { t: tgl, turnitin: teks_(t.turnitin) } };
}
function bimbinganRek_(r, B) {
  return B.baris.filter(function (o) { return teks_(o['ID Pengajuan']) === r.id; }).map(function (o) {
    return { id: teks_(o['ID']), tanggal: isoTanggal_(o['Tanggal']), bentuk: teks_(o['Bentuk']), materi: teks_(o['Materi']), catatan: teks_(o['Catatan Dosen']),
      durasi: parseInt(o['Durasi'], 10) || 0, parafMhs: teks_(o['Paraf Mahasiswa']), parafDsn: teks_(o['Paraf Dosen']), oleh: teks_(o['Dibuat Oleh']), _baris: o._baris };
  }).sort(function (a, b) { return a.tanggal < b.tanggal ? -1 : (a.tanggal > b.tanggal ? 1 : (a.id < b.id ? -1 : 1)); });
}
function rekapRek_(r, b, atur) {
  var sah = b.filter(function (x) { return x.parafMhs && x.parafDsn; });
  var akhir = b.length ? b[b.length - 1].tanggal : '', acuan = akhir && akhir > r.tanggalKeputusan ? akhir : r.tanggalKeputusan;
  var hari = Math.max(0, selisihHari_(acuan, hariIni_())), tahap = tahapRek_(r);
  return { jumlah: sah.length, tercatat: b.length, tungguDosen: b.filter(function (x) { return !x.parafDsn; }).length, tungguMhs: b.filter(function (x) { return !x.parafMhs; }).length,
    durasi: sah.reduce(function (n, x) { return n + x.durasi; }, 0), pertama: sah.length ? sah[0].tanggal : '', terakhir: sah.length ? sah[sah.length - 1].tanggal : '',
    hari: hari, macet: r.status === 'ACC' && tahap.kini !== 0 && hari > atur.batasMacet, tahapKini: tahap.kini, tahapNama: tahap.kini ? TAHAPAN_[tahap.kini - 1] : 'Selesai' };
}
function ringkasRek_(r, B, P, kontak, atur) {
  var b = bimbinganRek_(r, B), k = rekapRek_(r, b, atur), akhir = null;
  P.baris.forEach(function (o) { if (teks_(o['ID Pengajuan']) === r.id) akhir = o; });
  return { id: r.id, nama: r.nama, nim: r.nim, kelas: r.kelas, kekhususan: r.kekhususan, wa: nomorWa_(r.wa), judul: r.judulDisetujui, dosen: r.dosenPembimbing, waDosen: waDosen_(r.dosenPembimbing, kontak),
    tanggalAcc: r.tanggalKeputusan, rekap: k, pesanAkhir: akhir ? { waktu: teks_(akhir['Waktu']), dari: teks_(akhir['Dari']) } : null };
}
function ruang_(r, peran, atur) {
  var B = tabData_(KONFIG.TAB_BIMBINGAN, KOLOM_BIMBINGAN_), P = tabData_(KONFIG.TAB_PESAN, KOLOM_PESAN_), kontak = bacaKontak_();
  var h = ringkasRek_(r, B, P, kontak, atur), t = tahapRek_(r);
  h.status = r.status; h.batasMacet = atur.batasMacet; h.peran = peran;
  h.tahap = { daftar: t.daftar, kini: t.kini, turnitin: t.turnitin };
  h.bimbingan = bimbinganRek_(r, B).map(function (x) { delete x._baris; return x; });
  h.pesan = P.baris.filter(function (o) { return teks_(o['ID Pengajuan']) === r.id; }).map(function (o) {
    return { id: teks_(o['ID']), waktu: teks_(o['Waktu']), dari: teks_(o['Dari']), nama: teks_(o['Nama']), isi: teks_(o['Isi']) };
  });
  return h;
}

/* ------------------------------ hak akses ------------------------------ */
function aksesRuang_(peran, k1, k2) {
  var masuk = bacaMasuk_(), r = null, nama = '', atur = null;
  if (peran === 'mhs') {
    var n = teks_(k1), kd = teks_(k2).toUpperCase(), semua = [];
    masuk.baris.forEach(function (o) { if (teks_(o['NIM']) === n && teks_(o['Kode']).toUpperCase() === kd) semua.push(rekaman_(o)); });
    if (!n || !kd || !semua.length) galat_('NIM atau kode pengajuan tidak cocok. Kode didapat saat kamu mengajukan judul.');
    r = semua[semua.length - 1];
    for (var i = semua.length - 1; i >= 0; i--) if (semua[i].status === 'ACC') { r = semua[i]; break; }
    return { r: r, nama: r.nama, dari: 'mahasiswa', masuk: masuk, atur: bacaAtur_(), riwayat: semua };
  }
  if (peran === 'dsn') {
    var d = cekDosen_(k1);
    masuk.baris.forEach(function (o) { if (teks_(o['ID']) === teks_(k2)) r = rekaman_(o); });
    if (!r || r.status !== 'ACC' || cocokkanDosen_(r.dosenPembimbing, d.kontak) !== d.i) galat_('Mahasiswa ini bukan bimbingan Anda.');
    return { r: r, nama: d.nama, dari: 'dosen', masuk: masuk, atur: bacaAtur_() };
  }
