    masuk.baris.forEach(function (o) { if (teks_(o['ID']) === teks_(k2)) r = rekaman_(o); });
    if (!r) galat_('Data mahasiswa tidak ditemukan.');
    return { r: r, nama: atur.peran === 'kaprodi' ? 'Kaprodi S1 Ilmu Hukum' : 'Prodi S1 Ilmu Hukum', dari: 'prodi', masuk: masuk, atur: atur };
  }
  galat_('Jenis masuk tidak dikenal.');
}

/** Satu pintu untuk membuka dan mengubah ruang seorang mahasiswa. */
function apiRuang(peran, k1, k2, aksi, d) {
  pastikan_();
