  if (!aksi || aksi === 'buka') return kasJawab_('ruang.' + teks_(peran) + '.' + sidik_(teks_(k1) + '|' + teks_(k2).toUpperCase()), 30, function () { return apiRuangHitung_(peran, k1, k2, 'buka', d); });
  return apiRuangHitung_(peran, k1, k2, aksi, d);
}
function apiRuangHitung_(peran, k1, k2, aksi, d) {
