    return JSON.stringify({ nama: 'Buku Catatan Bimbingan - ' + r.nim + ' - ' + r.nama.replace(/[^\w ]+/g, '') + '.pdf', b64: Utilities.base64Encode(pdfB.getBytes()) });
  }
  if (aksi !== 'buka') {
    if (r.status !== 'ACC') galat_('Bimbingan dibuka setelah judul disetujui dan dosen pembimbing ditetapkan.');
    var kunci = LockService.getScriptLock();
    kunci.waitLock(25000);
    try { ubahRuang_(a, peran, aksi, d); } finally { kunci.releaseLock(); }
    if (aksi === 'tahap') { a = aksesRuang_(peran, k1, k2); r = a.r; }
  }
  var h = ruang_(r, peran, a.atur);
  if (peran === 'mhs') { h.kode = r.kode; h.pengajuan = a.riwayat.map(publik_).reverse(); }
  return JSON.stringify(h);
}
function ubahRuang_(a, peran, aksi, d) {
  var r = a.r, B, P, o, sekarang = waktuKini_();
  if (aksi === 'catat') {
    if (peran === 'adm') galat_('Catatan bimbingan hanya diisi mahasiswa dan dosen pembimbing.');
    var tgl = teks_(d.tanggal), bentuk = teks_(d.bentuk) === 'Daring' ? 'Daring' : 'Luring', materi = teks_(d.materi), catatan = teks_(d.catatan), durasi = parseInt(d.durasi, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(tgl)) galat_('Tanggal bimbingan belum diisi.');
