  if (!(sksT > 0 && sksT <= 220)) galat_('Isi jumlah SKS yang sudah ditempuh dan keluar nilainya, sesuai JUMLAH SKS pada DKN.');
  if (sksT < sksMinS) galat_('Menurut ' + (dkn ? 'DKN' : 'isianmu') + ' baru ' + sksT + ' SKS yang nilainya sudah keluar. Pengajuan sidang memerlukan minimal ' + sksMinS + ' SKS.');
  if ((!dkn || dkn.status !== 'cocok') && !d.nilaiSesuai) galat_('Centang pernyataan bahwa semua nilaimu minimal C, delapan mata kuliah dasar minimal BC, dan tidak ada mata kuliah ganda.');
  ps.sksTempuh = String(sksT); ps.sksDari = dkn ? 'DKN' : 'isian mahasiswa';
  return { peserta: ps, judul: judul, pembimbing: pembimbing, ipk: angka_(ipk, 2), nilai: nilai, dkn: dkn };
}

