/* --------------------- penguji (Kaprodi) dan jadwal --------------------- */
/** Kaprodi menetapkan ketua dan anggota penguji; pembimbing otomatis menjadi anggota/pembimbing. Ini sekaligus persetujuan untuk dijadwalkan. */
function apiAdminPenguji(pin, id, k) {
  kasBatal_();
  pastikan_();
  var atur = cekPin_(pin);
  k = k || {};
  var daftar = daftarPenguji_(null, atur), ketua = namaDosenBaku_(k.ketua, daftar), anggota = namaDosenBaku_(k.anggota, daftar);
  if (!ketua) galat_('Pilih ketua penguji dari daftar dosen.');
  if (!anggota) galat_('Pilih anggota penguji dari daftar dosen.');
  var kunci = LockService.getScriptLock();
  kunci.waitLock(25000);
  try {
    var t = bacaSidang_(), o = null;
    t.baris.forEach(function (b) { if (teks_(b['ID']) === teks_(id)) o = b; });
    if (!o) galat_('Pengajuan sidang tidak ditemukan.');
    var x = sidang_(o), pembimbing = teks_(k.pembimbing) ? namaDosenBaku_(k.pembimbing, daftar) : (x.pembimbing || namaDosenBaku_((resmiSidang_(x.nim) || {}).dosen, daftar));
    if (['Diterima', 'Disetujui', 'Terjadwal'].indexOf(x.status) < 0) galat_('Berkas pengajuan ini belum dinyatakan lengkap oleh admin sidang.');
    if (!pembimbing) galat_('Dosen pembimbing pengajuan ini belum tercatat. Isi dosen pembimbingnya, pilih dari daftar dosen.');
    if (samaDosen_(ketua, anggota)) galat_('Ketua dan anggota penguji harus dosen yang berbeda.');
    if (samaDosen_(ketua, pembimbing) || samaDosen_(anggota, pembimbing)) galat_('Dosen pembimbing sudah otomatis menjadi anggota/pembimbing. Pilih dosen lain sebagai ketua dan anggota.');
    if (x.status === 'Terjadwal') bentrokJadwal_(t, { id: x.id, ketua: ketua, anggota: anggota, pembimbing: pembimbing, tglUjian: x.tglUjian, jamUjian: x.jamUjian, ruang: x.ruang, zoom: x.zoom }, atur);
    ubahSel_(t, o._baris, { 'Ketua Penguji': ketua, 'Anggota Penguji': anggota, 'Dosen Pembimbing': pembimbing, 'Tgl Penetapan Penguji': hariIni_(), 'Status': x.status === 'Diterima' ? 'Disetujui' : x.status });
  } finally { kunci.releaseLock(); }
  return apiAdminData(pin);
}
function menit_(jam) { var m = /^(\d{2}):(\d{2})$/.exec(jam); return m ? (+m[1]) * 60 + (+m[2]) : -1; }
/** Menolak jadwal yang bertabrakan: ruang yang sama, atau dosen yang sama, pada waktu yang berimpit. */
function bentrokJadwal_(t, baru, atur) {
  var durasi = 60;
  try { var isi = buku_().getSheetByName(KONFIG.TAB_ATUR).getDataRange().getValues(); isi.forEach(function (b) { if (teks_(b[0]) === 'Durasi Ujian (menit)') { var v = parseInt(b[1], 10); if (v >= 15 && v <= 300) durasi = v; } }); } catch (e) { /* abaikan */ }
  t.baris.map(sidang_).forEach(function (y) {
    if (y.id === baru.id || y.status !== 'Terjadwal' || y.tglUjian !== baru.tglUjian) return;
    if (Math.abs(menit_(y.jamUjian) - menit_(baru.jamUjian)) >= durasi) return;
    if (baru.zoom || y.zoom) { if (baru.zoom && y.zoom && baru.zoom === y.zoom) galat_('Tautan Zoom ini sudah dipakai ujian ' + y.nama + ' pukul ' + y.jamUjian.replace(':', '.') + '. Pakai tautan lain atau waktu lain.'); }
    else if (y.ruang.toLowerCase() === baru.ruang.toLowerCase()) galat_(y.ruang + ' sudah dipakai ujian ' + y.nama + ' pukul ' + y.jamUjian.replace(':', '.') + '. Pilih ruang atau waktu lain.');
    [baru.ketua, baru.anggota, baru.pembimbing].forEach(function (d) {
      if (samaDosen_(d, y.ketua) || samaDosen_(d, y.anggota) || samaDosen_(d, y.pembimbing)) galat_(d + ' sudah menguji ' + y.nama + ' pukul ' + y.jamUjian.replace(':', '.') + ' di ' + y.ruang + '. Pilih waktu lain.');
    });
  });
}
/** Admin ujian menentukan (atau mengubah) waktu dan ruang ujian. Dewan penguji mengikuti penetapan Kaprodi. */
function apiAdminJadwal(pin, id, k) {
  kasBatal_();
  pastikan_();
  var atur = cekPin_(pin, true);
  k = k || {};
  var tgl = teks_(k.tanggal), jam = jam_(k.jam), ruang = teks_(k.ruang).slice(0, 40);
  var dt = /^(\d{4})-(\d{2})-(\d{2})$/.exec(tgl), du = dt ? new Date(Date.UTC(+dt[1], dt[2] - 1, +dt[3])) : null;
  if (!du || du.getUTCMonth() !== dt[2] - 1 || du.getUTCDate() !== +dt[3]) galat_('Isi tanggal ujian.');
  if (tgl < hariIni_()) galat_('Tanggal ujian sudah lewat.');
  if (!jam || menit_(jam) < 0 || menit_(jam) >= 24 * 60) galat_('Isi jam ujian, misalnya 09.00.');
  var kunci = LockService.getScriptLock();
  kunci.waitLock(25000);
  try {
    var t = bacaSidang_(), o = null;
    t.baris.forEach(function (b) { if (teks_(b['ID']) === teks_(id)) o = b; });
    if (!o) galat_('Pengajuan sidang tidak ditemukan.');
    var x = sidang_(o);
    if (x.status !== 'Disetujui' && x.status !== 'Terjadwal') galat_('Ujian baru bisa dijadwalkan setelah Kaprodi menetapkan dewan penguji.');
    var zoom = '';
    if (ujianDaring_(x.kelas)) {
      /* Eksekutif dan RPL: ujian lewat Zoom Meeting, admin menempelkan tautannya */
      zoom = teks_(k.zoom).replace(/\s+/g, '');
      if (!/^https:\/\/[A-Za-z0-9.-]+\.[A-Za-z]{2,}(\/\S*)?$/.test(zoom) || zoom.length > 400) galat_('Kelas ' + x.kelas + ' ujian lewat Zoom Meeting. Tempel tautan Zoom lengkap, diawali https://');
      ruang = 'Zoom Meeting';
    } else if (ruang.length < 2) galat_('Kelas Reguler ujian tatap muka. Isi ruang kelas tempat ujian.');
    bentrokJadwal_(t, { id: x.id, ketua: x.ketua, anggota: x.anggota, pembimbing: x.pembimbing, tglUjian: tgl, jamUjian: jam, ruang: ruang, zoom: zoom }, atur);
    ubahSel_(t, o._baris, { 'Tgl Ujian': tgl, 'Jam Ujian': jam, 'Ruang Ujian': ruang, 'Tautan Zoom': zoom, 'Status': 'Terjadwal' });
  } finally { kunci.releaseLock(); }
  return apiAdminData(pin);
}
